export type ParsedConvertInstruction<
  TProgram extends string = typeof MOCK_MARKET_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    market: TAccountMetas[1];
    ipo: TAccountMetas[2];
    oldMint: TAccountMetas[3];
    newMint: TAccountMetas[4];
    ownerOldAta: TAccountMetas[5];
    ownerNewAta: TAccountMetas[6];
    tokenProgramOld: TAccountMetas[7];
    tokenProgramNew: TAccountMetas[8];
  };
  data: ConvertInstructionData;
};

export function parseConvertInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedConvertInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      market: getNextAccount(),
      ipo: getNextAccount(),
      oldMint: getNextAccount(),
      newMint: getNextAccount(),
      ownerOldAta: getNextAccount(),
      ownerNewAta: getNextAccount(),
      tokenProgramOld: getNextAccount(),
      tokenProgramNew: getNextAccount(),
    },
    data: getConvertInstructionDataDecoder().decode(instruction.data),
  };
}
